---@param jsonData table
function OverseaStoreHomeDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData,key) and table.haskey(self,key) then
            self[key] = value
            if self[key].products then
                for _, v in ipairs(checkTable(self[key].products)) do
                    self:ConvertPrices(v)
                end
                table.sort(checkTable(self[key].products), function(a, b)
                    if checkInt(a.pos) ~= checkInt(b.pos) then
                        return checkInt(a.pos) < checkInt(b.pos)
                    else
                        return checkInt(a.productId) < checkInt(b.productId)
                    end
                end)
            end
        end
    end
end

---将prices转为需要的格式
function OverseaStoreHomeDojo:ConvertPrices(data)
    if not data.prices then return end

    local prices = {}
    for k, v in pairs(checkTable(data.prices)) do
        local tmp = {}
        tmp.current = v.current
        tmp.original = v.original
        tmp.currency = tonumber(k)
        table.insert(prices, tmp)
    end
    data.prices = prices
end

return OverseaStoreHomeDojo
